"use strict";var $=window.jQuery;$(document).ready(function(){var e=GMAP.gmap,o=e.latitude,n=e.longitude,t=e.marker,a=e.zoom,i=GMAP.infowindow,g=new google.maps.LatLng(o,n),m={zoom:a,center:g,mapTypeId:google.maps.MapTypeId.ROADMAP,disableDefaultUI:!0,animation:google.maps.Animation.DROP,scrollwheel:!1},r=new google.maps.Map(document.getElementById("map"),m),s=new google.maps.InfoWindow({content:i,maxWidth:500}),p=new google.maps.Marker({position:g,map:r,icon:t});google.maps.event.addListener(p,"click",function(){s.open(r,p),r.setZoom(parseInt(16))}),google.maps.event.addListener(window,"resize",function(){var e=r.getCenter();google.maps.event.trigger(r,"resize"),r.setCenter(e)})});